/**
 * better-auth Tables Schema
 *
 * Authoritative column set generated by `@better-auth/cli generate` for
 * the enabled plugins (username, organization + teams), then adapted to
 * the project conventions:
 *  - `betterauth_` table-name prefix (kept in sync with `auth.ts`)
 *  - UUID v7 primary keys generated by PostgreSQL (`generateId: false`)
 *  - relations are declared centrally in `../relation.ts`
 *
 * Regenerate the reference with `npm run betterauth:generate`.
 */

import { sql } from "drizzle-orm";
import {
  boolean,
  index,
  integer,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

/** Must match the prefix used for `modelName` in `auth.ts`. */
const BETTER_AUTH_TABLE_PREFIX = "betterauth_";

const betterauthUserTable = pgTable(`${BETTER_AUTH_TABLE_PREFIX}user`, {
  id: uuid("id").primaryKey().default(sql`uuidv7()`),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").default(false).notNull(),
  image: text("image"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at")
    .defaultNow()
    .$onUpdate(() => new Date())
    .notNull(),
  username: text("username").unique(),
  displayUsername: text("display_username"),
});

const betterauthSessionTable = pgTable(
  `${BETTER_AUTH_TABLE_PREFIX}session`,
  {
    id: uuid("id").primaryKey().default(sql`uuidv7()`),
    expiresAt: timestamp("expires_at").notNull(),
    token: text("token").notNull().unique(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => new Date())
      .notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: uuid("user_id")
      .notNull()
      .references(() => betterauthUserTable.id, { onDelete: "cascade" }),
    activeOrganizationId: uuid("active_organization_id"),
    activeTeamId: uuid("active_team_id"),
  },
  (table) => [
    index("betterauth_session_user_id_idx").on(table.userId),
  ],
);

const betterauthAccountTable = pgTable(
  `${BETTER_AUTH_TABLE_PREFIX}account`,
  {
    id: uuid("id").primaryKey().default(sql`uuidv7()`),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: uuid("user_id")
      .notNull()
      .references(() => betterauthUserTable.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at"),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at"),
    scope: text("scope"),
    password: text("password"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [
    index("betterauth_account_user_id_idx").on(table.userId),
  ],
);

const betterauthVerificationTable = pgTable(
  `${BETTER_AUTH_TABLE_PREFIX}verification`,
  {
    id: uuid("id").primaryKey().default(sql`uuidv7()`),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: timestamp("expires_at").notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [
    index("betterauth_verification_identifier_idx").on(table.identifier),
  ],
);

const betterauthOrganizationTable = pgTable(
  `${BETTER_AUTH_TABLE_PREFIX}organization`,
  {
    id: uuid("id").primaryKey().default(sql`uuidv7()`),
    name: text("name").notNull(),
    slug: text("slug").notNull().unique(),
    logo: text("logo"),
    createdAt: timestamp("created_at").notNull(),
    metadata: text("metadata"),
  },
  (table) => [
    uniqueIndex("betterauth_organization_slug_uidx").on(table.slug),
  ],
);

const betterauthTeamTable = pgTable(
  `${BETTER_AUTH_TABLE_PREFIX}team`,
  {
    id: uuid("id").primaryKey().default(sql`uuidv7()`),
    name: text("name").notNull(),
    memberCount: integer("member_count").default(0).notNull(),
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => betterauthOrganizationTable.id, {
        onDelete: "cascade",
      }),
    createdAt: timestamp("created_at").notNull(),
    updatedAt: timestamp("updated_at").$onUpdate(() => new Date()),
  },
  (table) => [
    index("betterauth_team_organization_id_idx").on(table.organizationId),
  ],
);

const betterauthTeamMemberTable = pgTable(
  `${BETTER_AUTH_TABLE_PREFIX}team_member`,
  {
    id: uuid("id").primaryKey().default(sql`uuidv7()`),
    teamId: uuid("team_id")
      .notNull()
      .references(() => betterauthTeamTable.id, { onDelete: "cascade" }),
    userId: uuid("user_id")
      .notNull()
      .references(() => betterauthUserTable.id, { onDelete: "cascade" }),
    membershipKey: text("membership_key").unique(),
    createdAt: timestamp("created_at"),
  },
  (table) => [
    index("betterauth_team_member_team_id_idx").on(table.teamId),
    index("betterauth_team_member_user_id_idx").on(table.userId),
  ],
);

const betterauthMemberTable = pgTable(
  `${BETTER_AUTH_TABLE_PREFIX}member`,
  {
    id: uuid("id").primaryKey().default(sql`uuidv7()`),
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => betterauthOrganizationTable.id, {
        onDelete: "cascade",
      }),
    userId: uuid("user_id")
      .notNull()
      .references(() => betterauthUserTable.id, { onDelete: "cascade" }),
    role: text("role").default("member").notNull(),
    createdAt: timestamp("created_at").notNull(),
  },
  (table) => [
    index("betterauth_member_organization_id_idx").on(table.organizationId),
    index("betterauth_member_user_id_idx").on(table.userId),
  ],
);

const betterauthInvitationTable = pgTable(
  `${BETTER_AUTH_TABLE_PREFIX}invitation`,
  {
    id: uuid("id").primaryKey().default(sql`uuidv7()`),
    organizationId: uuid("organization_id")
      .notNull()
      .references(() => betterauthOrganizationTable.id, {
        onDelete: "cascade",
      }),
    email: text("email").notNull(),
    role: text("role"),
    teamId: uuid("team_id"),
    status: text("status").default("pending").notNull(),
    expiresAt: timestamp("expires_at").notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    inviterId: uuid("inviter_id")
      .notNull()
      .references(() => betterauthUserTable.id, { onDelete: "cascade" }),
  },
  (table) => [
    index("betterauth_invitation_organization_id_idx")
      .on(table.organizationId),
    index("betterauth_invitation_email_idx").on(table.email),
  ],
);

export type BetterauthUser = typeof betterauthUserTable.$inferSelect;
export type BetterauthOrganization =
  typeof betterauthOrganizationTable.$inferSelect;
export type BetterauthMember = typeof betterauthMemberTable.$inferSelect;

export {
  betterauthAccountTable,
  betterauthInvitationTable,
  betterauthMemberTable,
  betterauthOrganizationTable,
  betterauthSessionTable,
  betterauthTeamMemberTable,
  betterauthTeamTable,
  betterauthUserTable,
  betterauthVerificationTable,
};
